#include <map>
#include <string>

// Comparator that orders strings by length first, then alphabetically
struct LengthCmp {
    bool operator()(const std::string& a, const std::string& b) const {
        if (a.length() != b.length()) {
            return a.length() < b.length();
        }
        return a < b; // Fall back to lexicographical comparison
    }
};

int main() {
    // Keys are ordered by length, then content.
    std::map<std::string, int, LengthCmp> length_map;
    length_map["a"] = 1;
    length_map["bb"] = 2;
    length_map["cc"] = 3;
    // Output order: 'a', 'bb', 'cc' (due to length sort)
}
